import { writeFile } from "node:fs/promises";
import { sigunguList } from "../server/weather/gridMap.ts";

const entries = sigunguList.map(
  ({ code, nx, ny }) => `  "${code}": { nx: ${nx}, ny: ${ny} },`,
);
await writeFile(
  new URL("../server/commute/grids.ts", import.meta.url),
  [
    "// Generated by scripts/build-commute-grids.mjs from the existing map grid mapping.",
    "export const commuteGrids: Record<string, { nx: number; ny: number }> = {",
    ...entries,
    "};\n",
  ].join("\n"),
);
